#include <iostream>
#include <map>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    vector<int> a = {1, -1, 1};
    long long k = 1, p = 0, ans = 0;
    map<long long, long long> freq;
    freq[0] = 1;
    for (int x : a) {
        p += x;
        auto it = freq.find(p - k);
        if (it != freq.end())
            ans += it->second;
        ++freq[p];
    }
    cout << ans;
}

