#include <iostream>
#include <map>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long k;
    cin >> n >> k;
    map<long long, long long> f;
    f[0] = 1;
    long long p = 0, ans = 0;
    for (int i = 0; i < n; ++i) {
        long long x;
        cin >> x;
        p += x;
        auto it = f.find(p - k);
        if (it != f.end())
            ans += it->second;
        ++f[p];
    }
    cout << ans;
}
